#include <cstdint>
#include <vector>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <limits>
#include <cstdio>
#include <cstdlib>

extern "C" void jv_solve(const double* cost, int n, int64_t* col_of_row) {
    const double INF = 1e18;
    // 1-indexed arrays
    std::vector<double> u(n + 1, 0.0), v(n + 1, 0.0);
    std::vector<int> p(n + 1, 0), way(n + 1, 0);
    std::vector<double> minv(n + 1);
    std::vector<char> used(n + 1);

