#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <queue>

// Sparse shortest augmenting path assignment.
// For each row, candidates are given (k of them). We also add a dummy edge to a slack
// column? No: we require the true optimum to lie within candidates. If a column is never
// a candidate it can never be matched; caller must ensure coverage.
//
// edges: for row i, cand_cols[i*k + t], cand_costs[i*k + t], t=0..k-1. Duplicates ok.
// Returns col_of_row. Returns 0 on success, 1 if some row unmatched (should not happen).

extern "C" int sap_solve(int n, int k, const int32_t* cand_cols, const double* cand_costs, int64_t* col_of_row) {
    const double INF = 1e100;
    // column adjacency: list of (row, cost) — built for reverse scans? We scan per-row candidate lists.
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);   // matched row for each column
    std::vector<int> col_of(n, -1);

    std::vector<double> dist(n);
    std::vector<int> parent_col(n);  // preceding column in augmenting path for a column
    std::vector<char> seen(n);

    for (int i = 0; i < n; i++) {
        // Dijkstra-like with potentials over columns reachable from row i via candidates,
        // but standard SAP: grow from free row.
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        std::fill(parent_col.begin(), parent_col.end(), -1);

        // initial: columns reachable directly from row i
        const int32_t* cols = cand_cols + (int64_t)i * k;
        const double* costs = cand_costs + (int64_t)i * k;
        for (int t = 0; t < k; t++) {
            int j = cols[t];
            double red = costs[t] - u[i] - v[j];
            if (red < dist[j]) {
                dist[j] = red;
                parent_col[j] = -2; // direct from start row; mark specially
            }
        }

        int sink = -1;
        double sink_dist = INF;
        while (true) {
            // pick unseen column with smallest dist
            int jmin = -1;
            double best = INF;
            for (int j = 0; j < n; j++) {
                if (!seen[j] && dist[j] < best) { best = dist[j]; jmin = j; }
            }
            if (jmin < 0 || best >= INF/2) break;
            seen[jmin] = 1;
            if (row_of_col[jmin] < 0) { sink = jmin; sink_dist = best; break; }
            // relax through the matched row of jmin
            int i2 = row_of_col[jmin];
            const int32_t* cols2 = cand_cols + (int64_t)i2 * k;
            const double* costs2 = cand_costs + (int64_t)i2 * k;
            double base = best + u[i2]; // dist[jmin] + u[i2] ; reduced: cost - u[i2] - v[j] + dist adjustment
            // The standard label update: dist[j] = min(dist[j], dist[jmin] + (cost(i2,j) - u[i2] - v[j]) - (cost(i2,jmin) - u[i2] - v[jmin]))
            // Since dist[jmin] == reduced slack accumulated and v potentials maintained, the common formulation:
            // dist[j] = min over i matched: dist[j_matched] + cost(i, j) - u[i] - v[j]
            // with u updated so that reduced costs of tight edges are 0. We'll use the textbook version below.
            for (int t = 0; t < k; t++) {
                int j = cols2[t];
                if (seen[j]) continue;
                double nd = best + costs2[t] - u[i2] - v[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    parent_col[j] = jmin;
                }
            }
        }
        if (sink < 0) return 1; // unmatched

        // update potentials
        // For every seen column, v[j] += dist[j] - sink_dist; u of matched rows adjusted.
        // Standard: u[i] += delta for rows in the alternating tree, v[j] -= delta.
        // Using reduced-cost distances: for seen columns j, v[j] += (dist[j] - sink_dist)? Let's use the
        // formulation consistent with initialization dist = cost - u - v.
        // After augmentation, set:
        //   for seen j: v[j] += dist[j] - sink_dist
        //   u[i_start] += sink_dist? Need feasibility. We'll follow the classic update:
        for (int j = 0; j < n; j++) {
            if (seen[j]) v[j] += dist[j] - sink_dist;
        }
        u[i] += sink_dist;
        // also rows matched to seen columns (except sink) need u update: u[row_of_col[j]] -= (dist[j]-sink_dist)
        // because their matched edge must stay tight. Let's do that.
        for (int j = 0; j < n; j++) {
            if (seen[j] && row_of_col[j] >= 0) {
                u[row_of_col[j]] -= dist[j] - sink_dist;
            }
        }

        // augment along parent_col
        int j = sink;
        int cur_row = i;
        while (true) {
            int prev = parent_col[j];
            row_of_col[j] = cur_row;
            col_of[cur_row] = j;
            if (prev == -2) break;
            // prev column's matched row becomes the row that now needs a column
            cur_row = row_of_col[prev];
            // wait, we just overwrote? No, prev != j and we haven't touched prev's row_of_col yet.
            // Actually row_of_col[prev] is still the old matched row. Good.
            j = prev;
        }
    }
    for (int i = 0; i < n; i++) col_of_row[i] = col_of[i];
    return 0;
}
