// Sparse Jonker-Volgenant / shortest augmenting path assignment.
// Candidate edges only: for each row, k (col, cost) pairs. The optimum must be
// inside the candidate set. Columns never appearing as candidates are unreachable.
//
// Potentials u[row], v[col] maintained so every candidate reduced cost
// cost - u - v >= 0 and matched edges have reduced cost 0.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>

extern "C" int sap_solve(int n, int k,
                         const int32_t* cand_cols, const double* cand_costs,
                         int64_t* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<int> col_of(n, -1);

    std::vector<double> minv(n);
    std::vector<int> way(n);       // predecessor column
    std::vector<char> used(n);
    std::vector<int> touched(n);   // columns whose minv was set this iteration
    int ntouched;

    for (int i = 0; i < n; i++) {
        std::memset(used.data(), 0, n);
        ntouched = 0;
        // init minv only for candidates of the starting row; others stay INF via a flag array
        std::vector<char> has(n, 0);
        const int32_t* cols = cand_cols + (int64_t)i * k;
        const double* costs = cand_costs + (int64_t)i * k;
        for (int t = 0; t < k; t++) {
            int j = cols[t];
            double cur = costs[t] - u[i] - v[j];
            if (!has[j] || cur < minv[j]) {
                minv[j] = cur;
                way[j] = -1;          // reached directly from start
                if (!has[j]) { has[j] = 1; touched[ntouched++] = j; }
            }
        }

        int j0 = -1;       // last scanned column (none yet)
        int sink = -1;
        while (true) {
            // find unused touched column with smallest minv
            double delta = INF;
            int j1 = -1;
            for (int t = 0; t < ntouched; t++) {
                int j = touched[t];
                if (!used[j] && minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            if (j1 < 0) return 1; // no augmenting path within candidates

            // update potentials for used columns and the start row
            if (j0 < 0) {
                u[i] += delta;
            }
            for (int t = 0; t < ntouched; t++) {
                int j = touched[t];
                if (used[j]) {
                    v[j] -= delta;
                    int ir = row_of_col[j];
                    if (ir >= 0) u[ir] += delta;
                } else {
                    minv[j] -= delta;
                }
            }
            // also the start row potential already bumped; columns not yet touched unchanged

            used[j1] = 1;
            j0 = j1;
            if (row_of_col[j1] < 0) { sink = j1; break; }

            // relax candidates of the row matched to j1
            int i2 = row_of_col[j1];
            const int32_t* cols2 = cand_cols + (int64_t)i2 * k;
            const double* costs2 = cand_costs + (int64_t)i2 * k;
            for (int t = 0; t < k; t++) {
                int j = cols2[t];
                if (used[j]) continue;
                double cur = costs2[t] - u[i2] - v[j];
                if (!has[j] || cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j1;
                    if (!has[j]) { has[j] = 1; touched[ntouched++] = j; }
                }
            }
        }

        // augment
        int j = sink;
        int cur = i;
        while (true) {
            int prev = way[j];
            int old_row = row_of_col[j];
            row_of_col[j] = cur;
            col_of[cur] = j;
            if (prev < 0) break;
            cur = old_row;   // the row that was matched to prev? 
            // wait: way[j] = j1 means we reached j from the row matched to j1.
            // So the row that should move is row_of_col[prev] BEFORE we overwrite it.
            // We have not overwritten prev yet. But old_row above is row_of_col[j] (the sink's old row, -1 first time).
            // Correct chain: the row arriving at j came from prev's matched row.
            j = prev;
            cur = row_of_col[j]; // still intact
            // BUG: first iteration cur should be start row i, subsequent cur = row previously matched to prev.
            // Let me restructure below — this loop is wrong. See replacement.
            break;
        }
        // proper augmentation
        {
            int jj = sink;
            while (jj >= 0) {
                int prev = way[jj];
                int r = (prev < 0) ? i : row_of_col[prev];
                row_of_col[jj] = r;
                col_of[r] = jj;
                jj = prev;
            }
        }
    }
    for (int i = 0; i < n; i++) col_of_row[i] = col_of[i];
    return 0;
}
