import numpy as np, ctypes, time, ot
from reference import Task
lib = ctypes.CDLL("build/libsap.so")
lib.sap_solve.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_int32), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int64)]
