    idx = np.ascontiguousarray(idx); costs = np.ascontiguousarray(costs)
    out = np.empty(n, dtype=np.int64)
    rc = lib.sap_solve(n, k, idx.ctypes.data_as(ctypes.POINTER(ctypes.c_int32)), costs.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), out.ctypes.data_as(ctypes.POINTER(ctypes.c_int64)))
