{"command":"cat > build/sap.cpp << 'EOF'
// Sparse shortest-augmenting-path assignment (Jonker-Volgenant style) over a
// candidate edge set. For each row i, k candidate columns with costs.
//
// Dual potentials u[row], v[col]. Reduced cost c' = c - u[i] - v[j] >= 0 for
// every candidate edge; matched edges have c' == 0.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>

extern "C" int sap_solve(int n, int k,
                         const int32_t* cand_cols, const double* cand_costs,
                         int64_t* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> match_col(n, -1);   // row -> col
    std::vector<int> match_row(n, -1);   // col -> row

    std::vector<double> dist(n);
    std::vector<int> pred(n);            // predecessor column on path
    std::vector<char> scanned(n);
    std::vector<int> reached;
    reached.reserve(n);
    std::vector<char> is_reached(n, 0);

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        std::fill(is_reached.begin(), is_reached.end(), 0);
        reached.clear();

        // seed distances from the free source row
        {
            const int32_t* cols = cand_cols + (int64_t)src * k;
            const double* costs = cand_costs + (int64_t)src * k;
            double us = u[src];
            for (int t = 0; t < k; t++) {
                int j = cols[t];
                double d = costs[t] - us - v[j];
                if (!is_reached[j]) {
                    is_reached[j] = 1;
                    dist[j] = d;
                    pred[j] = -1;
                    reached.push_back(j);
                } else if (d < dist[j]) {
                    dist[j] = d;
                    pred[j] = -1;
                }
            }
        }

        int sink = -1;
        while (true) {
            // extract min-distance unscanned reached column
            int jbest = -1;
            double dbest = INF;
            for (int j : reached) {
                if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            }
            if (jbest < 0) return 1;          // no path inside candidate set
            scanned[jbest] = 1;
            int r = match_row[jbest];
            if (r < 0) { sink = jbest; break; }

            // relax edges out of the row matched to jbest.
            // New label: dist[j] = dist[jbest] + reduced_cost(r, j)
            // because the matched edge (r, jbest) is tight, so the path cost
            // through it equals dist[jbest] plus the reduced cost of (r, j).
            const int32_t* cols = cand_cols + (int64_t)r * k;
            const double* costs = cand_costs + (int64_t)r * k;
            double ur = u[r];
            for (int t = 0; t < k; t++) {
                int j = cols[t];
                if (scanned[j]) continue;
                double d = dbest + costs[t] - ur - v[j];
                if (!is_reached[j]) {
                    is_reached[j] = 1;
                    dist[j] = d;
                    pred[j] = jbest;
                    reached.push_back(j);
                } else if (d < dist[j]) {
                    dist[j] = d;
                    pred[j] = jbest;
                }
            }
        }

        double dsink = dist[sink];
        // potential update: columns on the shortest-path tree get their
        // reduced distance; this keeps all scanned edges feasible and makes
        // the augmenting path tight.
        u[src] += dsink;
        for (int j : reached) {
            if (scanned[j]) {
                double delta = dist[j] - dsink;   // <= 0
                v[j] += delta;
                int r = match_row[j];
                if (r >= 0) u[r] -= delta;
            }
        }

        // augment along predecessor chain
        int j = sink;
        int r = src;
        while (j >= 0) {
            int pcol = pred[j];
            int r_next = (pcol < 0) ? -1 : match_row[pcol];
            match_row[j] = r;
            match_col[r] = j;
            r = r_next;
            j = pcol;
        }
    }

    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];
    return 0;
}
