#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cstdio>

static int feas_check(int n, int k, const int32_t* cand_cols, const double* cand_costs,
                      const std::vector<double>& u, const std::vector<double>& v,
                      const std::vector<int>& match_col, int stage) {
    int bad = 0;
    double worst = 0;
    for (int i = 0; i < n; i++) {
        for (int t = 0; t < k; t++) {
            int j = cand_cols[(int64_t)i*k + t];
            double rc = cand_costs[(int64_t)i*k + t] - u[i] - v[j];
            if (rc < -1e-8) { bad++; if (-rc > worst) worst = -rc; }
        }
        int j = match_col[i];
        if (j >= 0) {
            // find cost
            double c = 0; int found = 0;
            for (int t = 0; t < k; t++) if (cand_cols[(int64_t)i*k+t] == j) { c = cand_costs[(int64_t)i*k+t]; found = 1; break; }
            if (!found) { std::printf("stage %d row %d matched to non-candidate %d\n", stage, i, j); }
            else {
                double rc = c - u[i] - v[j];
                if (std::abs(rc) > 1e-7) { std::printf("stage %d matched edge (%d,%d) rc=%.3e\n", stage, i, j, rc); bad++; }
            }
        }
    }
    if (bad) std::printf("stage %d infeasible edges=%d worst=%.3e\n", stage, bad, worst);
    return bad;
}

extern "C" int sap_solve(int n, int k,
                         const int32_t* cand_cols, const double* cand_costs,
                         int64_t* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> match_col(n, -1);
    std::vector<int> match_row(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> reached; reached.reserve(n);
    std::vector<char> is_reached(n, 0);

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        std::fill(is_reached.begin(), is_reached.end(), 0);
        reached.clear();
        {
            const int32_t* cols = cand_cols + (int64_t)src * k;
            const double* costs = cand_costs + (int64_t)src * k;
            double us = u[src];
            for (int t = 0; t < k; t++) {
                int j = cols[t];
                double d = costs[t] - us - v[j];
                if (d < -1e-9) std::printf("src %d init neg reduced %.3e to col %d\n", src, d, j);
                if (!is_reached[j]) { is_reached[j]=1; dist[j]=d; pred[j]=-1; reached.push_back(j); }
                else if (d < dist[j]) { dist[j]=d; pred[j]=-1; }
            }
        }
        int sink = -1;
        while (true) {
            int jbest = -1; double dbest = INF;
            for (int j : reached) if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            if (jbest < 0) return 1;
            scanned[jbest] = 1;
            int r = match_row[jbest];
            if (r < 0) { sink = jbest; break; }
            const int32_t* cols = cand_cols + (int64_t)r * k;
            const double* costs = cand_costs + (int64_t)r * k;
            double ur = u[r];
            for (int t = 0; t < k; t++) {
                int j = cols[t];
                if (scanned[j]) continue;
                double d = dbest + costs[t] - ur - v[j];
                if (!is_reached[j]) { is_reached[j]=1; dist[j]=d; pred[j]=jbest; reached.push_back(j); }
                else if (d < dist[j]) { dist[j]=d; pred[j]=jbest; }
            }
        }
        double dsink = dist[sink];
        if (dsink < -1e-9) std::printf("src %d NEG dsink %.3e\n", src, dsink);

        u[src] += dsink;
        for (int j : reached) {
            if (scanned[j]) {
                double delta = dist[j] - dsink;
                v[j] += delta;
                int r = match_row[j];
                if (r >= 0) u[r] -= delta;
            }
        }
        int j = sink, r = src;
        while (j >= 0) {
            int pcol = pred[j];
            int r_next = (pcol < 0) ? -1 : match_row[pcol];
            match_row[j] = r;
            match_col[r] = j;
            r = r_next;
            j = pcol;
        }
        feas_check(n, k, cand_cols, cand_costs, u, v, match_col, src);
    }
    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];
    return 0;
}
