// Sparse Jonker-Volgenant assignment restricted to the k cheapest edges per row,
// plus a full-matrix dual certificate.
//
// solve_k(M, n, k, col_of_row, u_out, v_out, min_reduced):
//   returns 0 if a perfect matching was found within the candidate edges,
//   1 otherwise. Always fills u_out/v_out/min_reduced when it returns 0.
//   min_reduced is the minimum of M[i,j] - u[i] - v[j] over ALL entries; the
//   matching is optimal for the full matrix iff min_reduced >= -tol and every
//   matched edge is tight (guaranteed by the algorithm when it succeeds).
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

static void select_k(const double* row, int n, int k, int32_t* cols, double* costs) {
    // max-heap of size k holding the k smallest (cost, col)
    // heap arrays are 0-based, root = largest cost
    auto sift_down = [&](int len, int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]);
            std::swap(cols[i], cols[big]);
            i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k / 2 - 1; i >= 0; i--) sift_down(k, i);
    for (int j = k; j < n; j++) {
        if (row[j] < costs[0]) {
            costs[0] = row[j];
            cols[0] = j;
            sift_down(k, 0);
        }
    }
}

extern "C" int solve_k(const double* M, int n, int k,
                       int64_t* col_of_row, double* u_out, double* v_out,
                       double* min_reduced) {
    if (k > n) k = n;
    if (k < 1) k = 1;
    std::vector<int32_t> cand_cols((int64_t)n * k);
    std::vector<double> cand_costs((int64_t)n * k);
    for (int i = 0; i < n; i++) {
        select_k(M + (int64_t)i * n, n, k, cand_cols.data() + (int64_t)i * k,
                 cand_costs.data() + (int64_t)i * k);
    }

    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> match_col(n, -1), match_row(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n), is_reached(n, 0);
    std::vector<int> reached;
    reached.reserve(n);
    std::vector<int> chain;
    chain.reserve(n);

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        std::fill(is_reached.begin(), is_reached.end(), 0);
        reached.clear();

        const int32_t* sc = cand_cols.data() + (int64_t)src * k;
        const double* sv = cand_costs.data() + (int64_t)src * k;
        double us = u[src];
        for (int t = 0; t < k; t++) {
            int j = sc[t];
            double d = sv[t] - us - v[j];
            if (!is_reached[j]) { is_reached[j] = 1; dist[j] = d; pred[j] = -1; reached.push_back(j); }
            else if (d < dist[j]) { dist[j] = d; pred[j] = -1; }
        }

        int sink = -1;
        while (true) {
            int jbest = -1;
            double dbest = INF;
            for (int j : reached) {
                if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            }
            if (jbest < 0) return 1;
            scanned[jbest] = 1;
            int r = match_row[jbest];
            if (r < 0) { sink = jbest; break; }

            const int32_t* rc = cand_cols.data() + (int64_t)r * k;
            const double* rv = cand_costs.data() + (int64_t)r * k;
            double ur = u[r];
            for (int t = 0; t < k; t++) {
                int j = rc[t];
                if (scanned[j]) continue;
                double d = dbest + rv[t] - ur - v[j];
                if (!is_reached[j]) { is_reached[j] = 1; dist[j] = d; pred[j] = jbest; reached.push_back(j); }
                else if (d < dist[j]) { dist[j] = d; pred[j] = jbest; }
            }
        }

        double dsink = dist[sink];
        u[src] += dsink;
        for (int j : reached) {
            if (!scanned[j]) continue;
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = match_row[j];
            if (r >= 0) u[r] -= delta;
        }

        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        std::vector<int> newrow(L);
        for (int t = 0; t < L; t++) {
            int j = chain[t];
            newrow[t] = (pred[j] < 0) ? src : match_row[pred[j]];
        }
        for (int t = 0; t < L; t++) {
            match_row[chain[t]] = newrow[t];
            match_col[newrow[t]] = chain[t];
        }
    }

    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];
    if (u_out) std::memcpy(u_out, u.data(), n * sizeof(double));
    if (v_out) std::memcpy(v_out, v.data(), n * sizeof(double));

    if (min_reduced) {
        double mn = 1e100;
        for (int i = 0; i < n; i++) {
            const double* row = M + (int64_t)i * n;
            double ui = u[i];
            for (int j = 0; j < n; j++) {
                double r = row[j] - ui - v[j];
                if (r < mn) mn = r;
            }
        }
        *min_reduced = mn;
    }
    return 0;
}
