// Jonker-Volgenant shortest-augmenting-path assignment over the k cheapest
// candidate edges of each row, with a full-matrix reduced-cost certificate.
//
// solve_k returns 0 and fills col_of_row when a perfect matching exists inside
// the candidate set. If min_reduced != nullptr it scans the whole cost matrix
// and returns the minimum reduced cost M[i,j] - u[i] - v[j]; the matching is
// optimal for the full problem iff that value is >= 0 (within tolerance).
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

struct HeapNode { double key; int j; };

static void select_k(const double* row, int n, int k, int32_t* cols, double* costs) {
    auto sift_down = [&](int len, int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]);
            std::swap(cols[i], cols[big]);
            i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k / 2 - 1; i >= 0; i--) sift_down(k, i);
    for (int j = k; j < n; j++) {
        if (row[j] < costs[0]) { costs[0] = row[j]; cols[0] = j; sift_down(k, 0); }
    }
}

extern "C" int solve_k(const double* M, int n, int k,
                       int64_t* col_of_row, double* min_reduced) {
    if (k > n) k = n;
    if (k < 1) k = 1;

    std::vector<int32_t> cand_cols((int64_t)n * k);
    std::vector<double> cand_costs((int64_t)n * k);
    for (int i = 0; i < n; i++)
        select_k(M + (int64_t)i * n, n, k,
                 cand_cols.data() + (int64_t)i * k,
                 cand_costs.data() + (int64_t)i * k);

    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> match_col(n, -1), match_row(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n), is_reached(n);
    std::vector<int> reached;
    reached.reserve(n);
    std::vector<HeapNode> heap;
    heap.reserve(n * 2);
    std::vector<int> chain, newrow;
    chain.reserve(n);
    newrow.reserve(n);

    auto sift_up = [&](int i) {
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p].key <= heap[i].key) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };
    auto sift_down = [&](int i) {
        int sz = (int)heap.size();
        while (true) {
            int l = 2 * i + 1, r = l + 1, sm = i;
            if (l < sz && heap[l].key < heap[sm].key) sm = l;
            if (r < sz && heap[r].key < heap[sm].key) sm = r;
            if (sm == i) break;
            std::swap(heap[sm], heap[i]);
            i = sm;
        }
    };
    auto heap_push = [&](double key, int j) {
        heap.push_back({key, j});
        sift_up((int)heap.size() - 1);
    };
    auto heap_pop = [&]() -> HeapNode {
        HeapNode top = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        if (!heap.empty()) sift_down(0);
        return top;
    };

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        std::memset(is_reached.data(), 0, n);
        reached.clear();
        heap.clear();

        const int32_t* sc = cand_cols.data() + (int64_t)src * k;
        const double* sv = cand_costs.data() + (int64_t)src * k;
        double us = u[src];
        for (int t = 0; t < k; t++) {
            int j = sc[t];
            double d = sv[t] - us - v[j];
            if (!is_reached[j] || d < dist[j]) {
                if (!is_reached[j]) { is_reached[j] = 1; reached.push_back(j); }
                dist[j] = d;
                pred[j] = -1;
                heap_push(d, j);
            }
        }

        int sink = -1;
        double dsink = 0.0;
        while (true) {
            int jbest = -1;
            double dbest = 0.0;
            bool found = false;
            while (!heap.empty()) {
                HeapNode nd = heap_pop();
                if (scanned[nd.j]) continue;
                if (nd.key > dist[nd.j] + 1e-15) continue;   // stale
                jbest = nd.j;
                dbest = dist[nd.j];
                found = true;
                break;
            }
            if (!found) return 1;
            scanned[jbest] = 1;
            if (match_row[jbest] < 0) { sink = jbest; dsink = dbest; break; }

            int r = match_row[jbest];
            const int32_t* rc = cand_cols.data() + (int64_t)r * k;
            const double* rv = cand_costs.data() + (int64_t)r * k;
            double ur = u[r];
            for (int t = 0; t < k; t++) {
                int j = rc[t];
                if (scanned[j]) continue;
                double d = dbest + rv[t] - ur - v[j];
                if (!is_reached[j] || d < dist[j]) {
                    if (!is_reached[j]) { is_reached[j] = 1; reached.push_back(j); }
                    dist[j] = d;
                    pred[j] = jbest;
                    heap_push(d, j);
                }
            }
        }

        u[src] += dsink;
        for (int j : reached) {
            if (!scanned[j]) continue;
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = match_row[j];
            if (r >= 0) u[r] -= delta;
        }

        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++) {
            int j = chain[t];
            newrow[t] = (pred[j] < 0) ? src : match_row[pred[j]];
        }
        for (int t = 0; t < L; t++) {
            match_row[chain[t]] = newrow[t];
            match_col[newrow[t]] = chain[t];
        }
    }

    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];

    if (min_reduced) {
        double mn = 1e100;
        for (int i = 0; i < n; i++) {
            const double* row = M + (int64_t)i * n;
            double ui = u[i];
            int mc = match_col[i];
            for (int j = 0; j < n; j++) {
                double r = row[j] - ui - v[j];
                if (r < mn) mn = r;
            }
            (void)mc;
        }
        *min_reduced = mn;
    }
    return 0;
}
