// Jonker-Volgenant shortest augmenting path over the k cheapest edges per row.
// Candidate selection and the assignment are timed separately via the two
// exported functions so the bottleneck is measurable.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>

static void select_k(const double* row, int n, int k, int32_t* cols, double* costs) {
    auto sift_down = [&](int len, int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]);
            std::swap(cols[i], cols[big]);
            i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k / 2 - 1; i >= 0; i--) sift_down(k, i);
    for (int j = k; j < n; j++) if (row[j] < costs[0]) { costs[0] = row[j]; cols[0] = j; sift_down(k, 0); }
}

// SAP over a prepared candidate set. Returns 0 on success.
static int sap(int n, int k, const int32_t* cand_cols, const double* cand_costs,
               int64_t* col_of_row, double* u_out, double* v_out) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> match_col(n, -1), match_row(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n), is_reached(n);
    std::vector<int> reached; reached.reserve(n);
    std::vector<int> chain, newrow; chain.reserve(n);

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        std::memset(is_reached.data(), 0, n);
        reached.clear();

        const int32_t* sc = cand_cols + (int64_t)src * k;
        const double* sv = cand_costs + (int64_t)src * k;
        double us = u[src];
        for (int t = 0; t < k; t++) {
            int j = sc[t];
            double d = sv[t] - us - v[j];
            if (!is_reached[j] || d < dist[j]) {
                if (!is_reached[j]) { is_reached[j] = 1; reached.push_back(j); }
                dist[j] = d; pred[j] = -1;
            }
        }

        int sink = -1; double dsink = 0;
        int nr = (int)reached.size();
        while (true) {
            int jbest = -1; double dbest = INF;
            for (int t = 0; t < nr; t++) {
                int j = reached[t];
                if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            }
            if (jbest < 0) return 1;
            scanned[jbest] = 1;
            if (match_row[jbest] < 0) { sink = jbest; dsink = dbest; break; }
            int r = match_row[jbest];
            const int32_t* rc = cand_cols + (int64_t)r * k;
            const double* rv = cand_costs + (int64_t)r * k;
            double ur = u[r];
            for (int t = 0; t < k; t++) {
                int j = rc[t];
                if (scanned[j]) continue;
                double d = dbest + rv[t] - ur - v[j];
                if (!is_reached[j]) {
                    is_reached[j] = 1; dist[j] = d; pred[j] = jbest; reached.push_back(j); nr++;
                } else if (d < dist[j]) { dist[j] = d; pred[j] = jbest; }
            }
        }

        u[src] += dsink;
        for (int j : reached) if (scanned[j]) {
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = match_row[j];
            if (r >= 0) u[r] -= delta;
        }
        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++) newrow[t] = (pred[chain[t]] < 0) ? src : match_row[pred[chain[t]]];
        for (int t = 0; t < L; t++) { match_row[chain[t]] = newrow[t]; match_col[newrow[t]] = chain[t]; }
    }
    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];
    if (u_out) std::memcpy(u_out, u.data(), n * sizeof(double));
    if (v_out) std::memcpy(v_out, v.data(), n * sizeof(double));
    return 0;
}

extern "C" int solve_k(const double* M, int n, int k, int64_t* col_of_row, double* min_reduced) {
    if (k > n) k = n;
    std::vector<int32_t> cc((int64_t)n * k);
    std::vector<double> cv((int64_t)n * k);
    for (int i = 0; i < n; i++) select_k(M + (int64_t)i * n, n, k, cc.data() + (int64_t)i * k, cv.data() + (int64_t)i * k);
    std::vector<double> u(n), v(n);
    int rc = sap(n, k, cc.data(), cv.data(), col_of_row, min_reduced ? u.data() : nullptr, min_reduced ? v.data() : nullptr);
    if (rc) return rc;
    if (min_reduced) {
        double mn = 1e100;
        for (int i = 0; i < n; i++) {
            const double* row = M + (int64_t)i * n; double ui = u[i];
            for (int j = 0; j < n; j++) { double r = row[j] - ui - v[j]; if (r < mn) mn = r; }
        }
        *min_reduced = mn;
    }
    return 0;
}
