// Exact optimal assignment for a dense n x n cost matrix via a sparse
// Jonker-Volgenant shortest-augmenting-path solver with iterative pricing.
//
// The k nearest edges of each row are solved first. The resulting dual
// potentials certify optimality over the whole matrix; any edge with negative
// reduced cost is added and the problem is re-solved until the certificate is
// clean. The final assignment is therefore optimal for the full cost matrix.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

static void select_k(const double* row, int n, int k, int* cols, double* costs) {
    auto sift_down = [&](int len, int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]);
            std::swap(cols[i], cols[big]);
            i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k / 2 - 1; i >= 0; i--) sift_down(k, i);
    for (int j = k; j < n; j++)
        if (row[j] < costs[0]) { costs[0] = row[j]; cols[0] = j; sift_down(k, 0); }
}

// Shortest augmenting path over a CSR candidate graph.
// Returns 0 and fills col_of_row, u, v on success; 1 if no perfect matching.
static int sap(int n, const int* row_ptr, const int* cols, const double* costs,
               int64_t* col_of_row, double* u, double* v,
               std::vector<double>& dist, std::vector<int>& pred,
               std::vector<char>& scanned, std::vector<char>& is_reached,
               std::vector<int>& reached, std::vector<int>& heap_j,
               std::vector<double>& heap_key) {
    const double INF = 1e100;
    std::fill(u, u + n, 0.0);
    std::fill(v, v + n, 0.0);
    std::vector<int> match_col(n, -1), match_row(n, -1);
    std::vector<int> chain, newrow;

    int hsz = 0;
    auto push = [&](int j, double key) {
        int i = hsz++;
        heap_j[i] = j; heap_key[i] = key;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap_key[p] <= heap_key[i]) break;
            std::swap(heap_key[p], heap_key[i]);
            std::swap(heap_j[p], heap_j[i]);
            i = p;
        }
    };
    auto pop = [&](int& j, double& key) {
        j = heap_j[0]; key = heap_key[0];
        hsz--;
        if (hsz > 0) {
            heap_j[0] = heap_j[hsz]; heap_key[0] = heap_key[hsz];
            int i = 0;
            while (true) {
                int l = 2 * i + 1, r = l + 1, sm = i;
                if (l < hsz && heap_key[l] < heap_key[sm]) sm = l;
                if (r < hsz && heap_key[r] < heap_key[sm]) sm = r;
                if (sm == i) break;
                std::swap(heap_key[sm], heap_key[i]);
                std::swap(heap_j[sm], heap_j[i]);
                i = sm;
            }
        }
    };

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        std::memset(is_reached.data(), 0, n);
        reached.clear();
        hsz = 0;

        double us = u[src];
        for (int e = row_ptr[src]; e < row_ptr[src + 1]; e++) {
            int j = cols[e];
            double d = costs[e] - us - v[j];
            if (!is_reached[j] || d < dist[j]) {
                if (!is_reached[j]) { is_reached[j] = 1; reached.push_back(j); }
                dist[j] = d; pred[j] = -1;
                push(j, d);
            }
        }

        int sink = -1; double dsink = 0.0;
        while (true) {
            int jbest = -1; double dbest = 0.0; bool found = false;
            while (hsz > 0) {
                int j; double key; pop(j, key);
                if (scanned[j] || key != dist[j]) continue;
                jbest = j; dbest = key; found = true; break;
            }
            if (!found) return 1;
            scanned[jbest] = 1;
            if (match_row[jbest] < 0) { sink = jbest; dsink = dbest; break; }

            int r = match_row[jbest];
            double ur = u[r];
            for (int e = row_ptr[r]; e < row_ptr[r + 1]; e++) {
                int j = cols[e];
                if (scanned[j]) continue;
                double d = dbest + costs[e] - ur - v[j];
                if (!is_reached[j] || d < dist[j]) {
                    if (!is_reached[j]) { is_reached[j] = 1; reached.push_back(j); }
                    dist[j] = d; pred[j] = jbest;
                    push(j, d);
                }
            }
        }

        u[src] += dsink;
        for (int j : reached) if (scanned[j]) {
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = match_row[j];
            if (r >= 0) u[r] -= delta;
        }

        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++)
            newrow[t] = (pred[chain[t]] < 0) ? src : match_row[pred[chain[t]]];
        for (int t = 0; t < L; t++) {
            match_row[chain[t]] = newrow[t];
            match_col[newrow[t]] = chain[t];
        }
    }
    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];
    return 0;
}

extern "C" int emd_assign(const double* M, int n, int64_t* col_of_row) {
    const double TOL = 1e-9;
    const int K0 = 24;

    // workspace
    std::vector<double> dist(n), u(n), v(n), heap_key(n * 64);
    std::vector<int> pred(n), reached, heap_j(n * 64);
    std::vector<char> scanned(n), is_reached(n);
    reached.reserve(n);

    // candidate edges, CSR, grown across pricing rounds
    std::vector<std::vector<int>> clist(n);
    std::vector<std::vector<double>> cval(n);
    for (int i = 0; i < n; i++) { clist[i].reserve(K0 * 2); cval[i].reserve(K0 * 2); }

    std::vector<int> tmp_cols(n);
    std::vector<double> tmp_costs(n);
    std::vector<char> present(n, 0);
    for (int i = 0; i < n; i++) {
        int k = std::min(K0, n);
        select_k(M + (int64_t)i * n, n, k, tmp_cols.data(), tmp_costs.data());
        for (int t = 0; t < k; t++) { clist[i].push_back(tmp_cols[t]); cval[i].push_back(tmp_costs[t]); }
    }

    std::vector<int> row_ptr(n + 1), cols;
    std::vector<double> costs;
    cols.reserve((int64_t)n * K0 * 4);
    costs.reserve((int64_t)n * K0 * 4);

    auto build_csr = [&]() {
        row_ptr[0] = 0;
        cols.clear(); costs.clear();
        for (int i = 0; i < n; i++) {
            for (size_t t = 0; t < clist[i].size(); t++) {
                cols.push_back(clist[i][t]);
                costs.push_back(cval[i][t]);
            }
            row_ptr[i + 1] = (int)cols.size();
        }
    };

    for (int round = 0; round < 50; round++) {
        build_csr();
        int need = (int)cols.size() + n * 8 + 8;
        if ((int)heap_j.size() < need) { heap_j.resize(need); heap_key.resize(need); }
        int rc = sap(n, row_ptr.data(), cols.data(), costs.data(), col_of_row,
                     u.data(), v.data(), dist, pred, scanned, is_reached, reached, heap_j, heap_key);
        if (rc) {
            // candidate graph has no perfect matching: widen every row
            int added = 0;
            for (int i = 0; i < n; i++) {
                int have = (int)clist[i].size();
                int want = std::min(n, have * 2 + 1);
                if (want <= have) continue;
                select_k(M + (int64_t)i * n, n, want, tmp_cols.data(), tmp_costs.data());
                for (int j : clist[i]) present[j] = 1;
                for (int t = 0; t < want; t++) if (!present[tmp_cols[t]]) {
                    clist[i].push_back(tmp_cols[t]); cval[i].push_back(tmp_costs[t]); added++;
                }
                for (int j : clist[i]) present[j] = 0;
            }
            if (!added) return 2;
            continue;
        }

        // price: find edges with negative reduced cost and add the worst ones
        int added = 0;
        for (int i = 0; i < n; i++) {
            const double* row = M + (int64_t)i * n;
            double ui = u[i];
            for (int j : clist[i]) present[j] = 1;
            int worst_j = -1; double worst = -TOL;
            int extra = 0;
            for (int j = 0; j < n; j++) {
                if (present[j]) continue;
                double r = row[j] - ui - v[j];
                if (r < -TOL) {
                    extra++;
                    if (r < worst) { worst = r; worst_j = j; }
                }
            }
            for (int j : clist[i]) present[j] = 0;
            if (worst_j >= 0) {
                clist[i].push_back(worst_j);
                cval[i].push_back(M[(int64_t)i * n + worst_j]);
                added++;
                (void)extra;
            }
        }
        if (!added) return 0;   // certified optimal
    }
    return 3;
}
