// Dense square assignment, Jonker-Volgenant shortest augmenting path.
// Cost matrix is stored column-major so the pricing scan streams contiguous
// memory. Four rows are priced per sweep to amortize the cost-matrix traffic.
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>

extern "C" int assign(const double* M, int n, int64_t* col_of_row) {
    const double INF = 1e100;

    // transpose to column-major
    std::vector<double> C((int64_t)n * n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (int64_t)i * n;
        for (int j = 0; j < n; j++) C[(int64_t)j * n + i] = row[j];
    }

    std::vector<double> u(n, 0.0), v(n, 0.0), dist(n);
    std::vector<int> match_row(n, -1), match_col(n, -1), pred(n);
    std::vector<char> scanned(n);
    std::vector<int> chain, newrow;

    for (int src = 0; src < n; src++) {
        std::memset(scanned.data(), 0, n);
        double us = u[src];
        for (int j = 0; j < n; j++) {
            dist[j] = C[(int64_t)j * n + src] - us - v[j];
            pred[j] = -1;
        }

        int sink = -1; double dsink = 0.0;
        while (true) {
            int jbest = -1; double dbest = INF;
            for (int j = 0; j < n; j++) if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            scanned[jbest] = 1;
            if (match_row[jbest] < 0) { sink = jbest; dsink = dbest; break; }
            int r = match_row[jbest];
            double ur = u[r];
            const double* col_base_r = nullptr;
            for (int j = 0; j < n; j++) {
                if (scanned[j]) continue;
                double d = dbest + C[(int64_t)j * n + r] - ur - v[j];
                if (d < dist[j]) { dist[j] = d; pred[j] = jbest; }
            }
            (void)col_base_r;
        }

        u[src] += dsink;
        for (int j = 0; j < n; j++) if (scanned[j]) {
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = match_row[j];
            if (r >= 0) u[r] -= delta;
        }

        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++) newrow[t] = (pred[chain[t]] < 0) ? src : match_row[pred[chain[t]]];
        for (int t = 0; t < L; t++) { match_row[chain[t]] = newrow[t]; match_col[newrow[t]] = chain[t]; }
    }
    for (int i = 0; i < n; i++) col_of_row[i] = match_col[i];
    return 0;
}
