// Bertsekas auction algorithm with epsilon scaling for the dense square
// assignment problem. Returns the column assigned to each row.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

extern "C" int auction_solve(const double* M, int n, int64_t* col_of_row) {
    double maxc = 0.0;
    for (int64_t i = 0; i < (int64_t)n * n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 4.0;
    if (eps < 1e-6) eps = 1e-6;
    const double target = 1e-10;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);          // column -> row
    std::vector<int> free_rows(n), bid_col(n);
    std::vector<double> bid_val(n);
    std::vector<char> col_taken(n);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int guard = 0;
        const int guard_max = n * 100;
        while (nfree > 0 && guard++ < guard_max) {
            int nbids = nfree;
            for (int f = 0; f < nfree; f++) {
                int i = free_rows[f];
                const double* row = M + (int64_t)i * n;
                int j1 = 0;
                double best = -row[0] - price[0];
                double second = -1e300;
                for (int j = 1; j < n; j++) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; j1 = j; }
                    else if (val > second) second = val;
                }
                bid_col[f] = j1;
                bid_val[f] = price[j1] + (best - second) + eps;
            }
            // assign: for each column the highest bidder wins
            std::memset(col_taken.data(), 0, n);
            // collect winners
            std::vector<int> win_row(n, -1);
            std::vector<double> win_bid(n, -1e300);
            for (int f = 0; f < nbids; f++) {
                int j = bid_col[f];
                if (bid_val[f] > win_bid[j]) { win_bid[j] = bid_val[f]; win_row[j] = free_rows[f]; }
            }
            std::vector<char> still_free(n, 0);
            for (int f = 0; f < nfree; f++) still_free[free_rows[f]] = 1;
            for (int j = 0; j < n; j++) {
                int i = win_row[j];
                if (i < 0) continue;
                int prev = owner[j];
                if (prev >= 0) still_free[prev] = 1;
                owner[j] = i;
                price[j] = win_bid[j];
                still_free[i] = 0;
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (still_free[i]) free_rows[nfree++] = i;
        }
        if (nfree > 0) return 1;
        if (eps <= target) break;
        eps *= 0.25;
        if (eps < target) eps = target;
    }
