// Sparse auction with epsilon scaling. Each row bids only among its k nearest
// columns. After convergence the dual prices are checked against the full cost
// matrix; violated edges are added and the auction continues until certified.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

struct Edge { int j; double c; };

static void k_nearest(const double* row, int n, int k, std::vector<Edge>& out) {
    std::vector<double> costs(k);
    std::vector<int> cols(k);
    auto sift = [&](int len, int i) {
        while (true) {
            int l = 2*i+1, r = l+1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]); std::swap(cols[i], cols[big]); i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k/2-1; i >= 0; i--) sift(k, i);
    for (int j = k; j < n; j++) if (row[j] < costs[0]) { costs[0] = row[j]; cols[0] = j; sift(k, 0); }
    out.resize(k);
    for (int t = 0; t < k; t++) out[t] = {cols[t], costs[t]};
}

extern "C" int auction_sparse(const double* M, int n, int64_t* col_of_row) {
    int k = 32;
    if (k > n) k = n;
    std::vector<std::vector<Edge>> edges(n);
    for (int i = 0; i < n; i++) { edges[i].reserve(k * 2); k_nearest(M + (int64_t)i*n, n, k, edges[i]); }

    std::vector<char> present(n, 0);
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), free_rows(n);
    std::vector<int> bid_col(n);
    std::vector<double> bid_val(n);

    double maxc = 0.0;
    for (int64_t t = 0; t < (int64_t)n*n; t++) if (M[t] > maxc) maxc = M[t];
    const double final_eps = 1e-10;

    auto run_phase = [&](double eps) -> int {
        std::fill(owner.begin(), owner.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int guard = 0;
        while (nfree > 0) {
            if (++guard > n * 200) return 1;
            for (int f = 0; f < nfree; f++) {
                int i = free_rows[f];
                const auto& el = edges[i];
                int j1 = el[0].j;
                double best = -el[0].c - price[j1];
                double second = -1e300;
                for (size_t t = 1; t < el.size(); t++) {
                    double val = -el[t].c - price[el[t].j];
                    if (val > best) { second = best; best = val; j1 = el[t].j; }
                    else if (val > second) second = val;
                }
                if (second < -1e200) second = best - 1.0;  // single candidate
                bid_col[f] = j1;
                bid_val[f] = price[j1] + (best - second) + eps;
            }
            std::vector<int> win_row(n, -1);
            std::vector<double> win_bid(n, -1e300);
            for (int f = 0; f < nfree; f++) {
                int j = bid_col[f];
                if (bid_val[f] > win_bid[j]) { win_bid[j] = bid_val[f]; win_row[j] = free_rows[f]; }
            }
            std::vector<char> still_free(n, 0);
            for (int f = 0; f < nfree; f++) still_free[free_rows[f]] = 1;
            for (int j = 0; j < n; j++) {
                int i = win_row[j];
                if (i < 0) continue;
                int prev = owner[j];
                if (prev >= 0) still_free[prev] = 1;
                owner[j] = i;
                price[j] = win_bid[j];
                still_free[i] = 0;
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (still_free[i]) free_rows[nfree++] = i;
        }
        return 0;
    };

    for (int round = 0; round < 40; round++) {
        double eps = maxc / 4.0;
        // prices persist across rounds (warm start) but owner is reset per phase
        bool ok = true;
        while (true) {
            if (run_phase(eps)) { ok = false; break; }
            if (eps <= final_eps) break;
            eps *= 0.25;
            if (eps < final_eps) eps = final_eps;
        }
        if (!ok) {
            // widen every row
            int added = 0;
            for (int i = 0; i < n; i++) {
                int want = std::min(n, (int)edges[i].size() * 2);
                if (want <= (int)edges[i].size()) continue;
                std::vector<Edge> neu;
                k_nearest(M + (int64_t)i*n, n, want, neu);
                for (auto& e : edges[i]) present[e.j] = 1;
                for (auto& e : neu) if (!present[e.j]) { edges[i].push_back(e); added++; }
                for (auto& e : edges[i]) present[e.j] = 0;
            }
            if (!added) return 2;
            continue;
        }
        // certify against full matrix: row profit = -price[col] - M[row,col]
        int added = 0;
        for (int i = 0; i < n; i++) {
            int mc = -1;
            for (int j = 0; j < n; j++) if (owner[j] == i) { mc = j; break; }
            double my = -price[mc] - M[(int64_t)i*n + mc];
            for (auto& e : edges[i]) present[e.j] = 1;
            const double* row = M + (int64_t)i*n;
            int worst = -1; double worstgap = 1e-9;
            for (int j = 0; j < n; j++) {
                if (present[j]) continue;
                double gap = (-price[j] - row[j]) - my;
                if (gap > worstgap) { worstgap = gap; worst = j; }
            }
            for (auto& e : edges[i]) present[e.j] = 0;
            if (worst >= 0) { edges[i].push_back({worst, row[worst]}); added++; }
        }
        if (!added) {
            for (int j = 0; j < n; j++) col_of_row[owner[j]] = j;
            return 0;
        }
    }
    return 3;
}
