// Bertsekas auction with epsilon scaling. Bidding sweeps run on several
// threads; each thread handles a slice of the free rows.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <thread>

extern "C" int auction_solve(const double* M, int n, int64_t* col_of_row, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    if (nthreads > n) nthreads = n;
    double maxc = 0.0;
    for (int64_t i = 0; i < (int64_t)n * n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 4.0;
    if (eps < 1e-6) eps = 1e-6;
    const double target = 1e-10;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> free_rows(n), bid_col(n);
    std::vector<double> bid_val(n);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int guard = 0;
        const int guard_max = n * 100;
        while (nfree > 0 && guard++ < guard_max) {
            int nt = nthreads;
            if (nfree < nt * 4) nt = 1;
            auto work = [&](int f0, int f1) {
                for (int f = f0; f < f1; f++) {
                    int i = free_rows[f];
                    const double* row = M + (int64_t)i * n;
                    int j1 = 0;
                    double best = -row[0] - price[0];
                    double second = -1e300;
                    for (int j = 1; j < n; j++) {
                        double val = -row[j] - price[j];
                        if (val > best) { second = best; best = val; j1 = j; }
                        else if (val > second) second = val;
                    }
                    bid_col[f] = j1;
                    bid_val[f] = price[j1] + (best - second) + eps;
                }
            };
            if (nt == 1) {
                work(0, nfree);
            } else {
                std::vector<std::thread> th;
                int chunk = (nfree + nt - 1) / nt;
                for (int t = 0; t < nt; t++) {
                    int f0 = t * chunk, f1 = std::min(nfree, f0 + chunk);
                    if (f0 >= f1) break;
                    th.emplace_back(work, f0, f1);
