            for (int f = 0; f < nfree; f++) still_free[free_rows[f]] = 1;
            for (int j = 0; j < n; j++) {
                int i = win_row[j];
                if (i < 0) continue;
                int prev = owner[j];
                if (prev >= 0) still_free[prev] = 1;
                owner[j] = i;
                price[j] = win_bid[j];
                still_free[i] = 0;
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (still_free[i]) free_rows[nfree++] = i;
        }
        if (nfree > 0) return 1;
        if (eps <= target) break;
        eps *= 0.25;
        if (eps < target) eps = target;
    }
    for (int j = 0; j < n; j++) col_of_row[owner[j]] = j;
    return 0;
