#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

static void knn(const double* row, int n, int k, int* cols, double* costs) {
    auto sift = [&](int len, int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]);
            std::swap(cols[i], cols[big]);
            i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k / 2 - 1; i >= 0; i--) sift(k, i);
    for (int j = k; j < n; j++) if (row[j] < costs[0]) { costs[0] = row[j]; cols[0] = j; sift(k, 0); }
}

extern "C" int auction_k(const double* M, int n, int k, int64_t* col_of_row) {
    if (k > n) k = n;
    std::vector<int> cc((int64_t)n * k);
    std::vector<double> cv((int64_t)n * k);
    for (int i = 0; i < n; i++) knn(M + (int64_t)i * n, n, k, cc.data() + (int64_t)i * k, cv.data() + (int64_t)i * k);

    double maxc = 0.0;
    for (int i = 0; i < n; i++) for (int t = 0; t < k; t++) if (cv[(int64_t)i * k + t] > maxc) maxc = cv[(int64_t)i * k + t];
    double eps = maxc / 4.0;
    const double target = 1e-10;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), free_rows(n), bid_col(n);
    std::vector<double> bid_val(n);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int guard = 0;
        while (nfree > 0) {
            if (++guard > n * 300) return 1;
            for (int f = 0; f < nfree; f++) {
                int i = free_rows[f];
                const int* cols = cc.data() + (int64_t)i * k;
                const double* costs = cv.data() + (int64_t)i * k;
                int j1 = cols[0];
                double best = -costs[0] - price[j1];
                double second = -1e300;
                for (int t = 1; t < k; t++) {
                    int j = cols[t];
                    double val = -costs[t] - price[j];
                    if (val > best) { second = best; best = val; j1 = j; }
                    else if (val > second) second = val;
                }
                bid_col[f] = j1;
                bid_val[f] = price[j1] + (best - second) + eps;
            }
            std::vector<int> win_row(n, -1);
            std::vector<double> win_bid(n, -1e300);
            for (int f = 0; f < nfree; f++) {
                int j = bid_col[f];
                if (bid_val[f] > win_bid[j]) { win_bid[j] = bid_val[f]; win_row[j] = free_rows[f]; }
            }
            std::vector<char> still_free(n, 0);
            for (int f = 0; f < nfree; f++) still_free[free_rows[f]] = 1;
            for (int j = 0; j < n; j++) {
                int i = win_row[j];
                if (i < 0) continue;
                int prev = owner[j];
                if (prev >= 0) still_free[prev] = 1;
                owner[j] = i;
                price[j] = win_bid[j];
                still_free[i] = 0;
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (still_free[i]) free_rows[nfree++] = i;
        }
        if (eps <= target) break;
        eps *= 0.25;
        if (eps < target) eps = target;
    }
    for (int j = 0; j < n; j++) col_of_row[owner[j]] = j;
    return 0;
}
