// Network simplex for the dense transportation problem, following the
// implementation used by or-tools / LEMON (full_bipartite_graph, k=2 parent
// links, block pricing). For uniform supplies this returns a basic optimal
// solution; which one depends on the pivot rule below.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <limits>

static constexpr int BLOCK = 2000;

extern "C" int network_simplex(const double* M, const double* supply, const double* demand,
                               int n, int m, double* flow_out) {
    // nodes: sources 0..n-1, sinks n..n+m-1, root n+m
    const int N = n + m;
    const int ROOT = N;
    const int NN = N + 1;
    const double INF = std::numeric_limits<double>::infinity();

    std::vector<int> parent(NN), pred(NN), thread(NN), succ_num(NN), last_succ(NN), parent_next(NN, -1);
    std::vector<double> pi(NN, 0.0), flow(NN, 0.0);
    std::vector<char> forward(NN, 1);

    auto arc_cost = [&](int u, int v) -> double {
        // u source (0..n-1), v sink index (0..m-1)
        return M[(int64_t)u * m + v];
    };

    // initial basis: source i -> sink i%m, plus root arcs
    // build tree: root connected to every sink with artificial zero-cost? Use big cost artificial arcs
    // from root to all sinks and all sources, then pivot them out. Simpler: connect each source to
    // its cheapest sink and repair with root arcs. For correctness we use the classic construction:
    // every source and sink hangs off the root through an artificial arc of cost ART.
    const double ART = 1e6;
    for (int i = 0; i < NN; i++) { parent[i] = ROOT; pred[i] = ROOT; forward[i] = 0; succ_num[i] = 1; last_succ[i] = i; thread[i] = i + 1; }
    thread[NN - 1] = 0;
    succ_num[ROOT] = NN;
    last_succ[ROOT] = NN - 1;
    parent[ROOT] = -1;
    flow[ROOT] = 0;
    // artificial flow: sources supply, sinks demand
    for (int i = 0; i < n; i++) flow[i] = supply[i];
    for (int j = 0; j < m; j++) flow[n + j] = demand[j];
    pi[ROOT] = 0;
    for (int i = 0; i < n; i++) pi[i] = ART;       // reduced: cost(root,i)=ART, forward=0 so pi[i] = pi[root] + ART
    for (int j = 0; j < m; j++) pi[n + j] = -ART;

    auto reduced = [&](int s, int t) -> double {
        return arc_cost(s, t) - pi[s] + pi[n + t];
    };

    // entering arc search state
    int next_s = 0, next_t = 0;

    auto find_entering = [&](int& es, int& et, double& erc) -> bool {
        double best = 0.0; bool found = false;
        int scanned = 0;
        int s = next_s, t = next_t;
        int total = n * m;
        for (int c = 0; c < total && scanned < BLOCK; c++) {
            double rc = reduced(s, t);
            scanned++;
            if (rc < best) { best = rc; es = s; et = t; found = true; }
            if (++t == m) { t = 0; if (++s == n) s = 0; }
        }
        next_s = s; next_t = t;
        erc = best;
        return found;
    };

    auto update_tree = [&](int u_in, int v_in) {
        // pivot entering arc source u_in -> sink v_in (node ids)
        int u = u_in, v = n + v_in;
        // find apex and the leaving arc (minimum residual on the path)
        // walk both sides to root collecting paths
        std::vector<int> path_u, path_v;
        std::vector<char> seen(NN, 0);
        for (int x = u; x != -1; x = parent[x]) { path_u.push_back(x); seen[x] = 1; }
        int apex = -1;
        for (int x = v; x != -1; x = parent[x]) { if (seen[x]) { apex = x; break; } path_v.push_back(x); }
        // leaving arc: min flow on the u-side reverse arcs and v-side forward arcs
        double delta = std::numeric_limits<double>::infinity();
        int leave = -1; // node whose parent arc leaves
        bool leave_on_u = true;
        for (int x : path_u) {
            if (x == apex) break;
            if (flow[x] < delta) { delta = flow[x]; leave = x; leave_on_u = true; }
        }
        for (int x : path_v) {
            if (flow[x] < delta) { delta = flow[x]; leave = x; leave_on_u = false; }
        }
        // update flows
        for (int x : path_u) { if (x == apex) break; flow[x] -= delta; }
        for (int x : path_v) flow[x] += delta;
        if (!std::isfinite(delta)) return false;

        // if entering arc's head side: flow on new arc = delta. Represent by re-parenting.
        // Reattach the subtree. Standard approach: reverse the parent links from the leaving
        // node up to where the entering arc attaches, then attach.
        int join = leave_on_u ? u : v;   // the endpoint of the entering arc on the leaving side
        int other = leave_on_u ? v : u;

        // reverse parent links along join -> leave
        std::vector<int> chain;
        for (int x = join; x != leave; x = parent[x]) chain.push_back(x);
        chain.push_back(leave);
        for (int i = (int)chain.size() - 1; i > 0; i--) {
            int x = chain[i], p = chain[i - 1];
            parent[x] = p;
            flow[x] = flow[p];
            forward[x] = !forward[p];
        }
        parent[join] = other;
        flow[join] = delta;
        forward[join] = leave_on_u ? 1 : 0;

        // recompute potentials in the moved subtree and rebuild thread/succ links globally (N is small enough per pivot? no)
        // full rebuild of traversal structure from parent links — O(N) per pivot, acceptable if pivots are few
        std::vector<std::vector<int>> children(NN);
        for (int x = 0; x < NN; x++) if (x != ROOT && parent[x] >= 0) children[parent[x]].push_back(x);
        int timer = 0;
        std::vector<int> order;
        order.reserve(NN);
        std::vector<int> stack = {ROOT};
        std::vector<int> post(NN, 0);
        // DFS
        std::vector<int> state(NN, 0);
        while (!stack.empty()) {
            int x = stack.back();
            if (state[x] == 0) {
                order.push_back(x);
                state[x] = 1;
                for (int c : children[x]) stack.push_back(c);
            } else stack.pop_back();
        }
        for (int i = 0; i < NN; i++) thread[order[i]] = order[(i + 1) % NN];
        // potentials: pi[child] from pi[parent]
        for (int x : order) {
            if (x == ROOT) { pi[x] = 0; continue; }
            int p = parent[x];
            if (x < n && p >= n && p != ROOT) {
                // source child of sink: arc source->sink, forward?
            }
            // determine arc cost between x and parent
            int snode, tnode;
            if (x < n && p >= n && p < ROOT) { snode = x; tnode = p - n; }
            else if (p < n && x >= n && x < ROOT) { snode = p; tnode = x - n; }
            else { // artificial root arc
                pi[x] = (x < n) ? ART : -ART;
                continue;
            }
            double c = arc_cost(snode, tnode);
            if (parent[x] == p && x == snode) pi[x] = pi[p] + c;       // source below sink: pi[s] = pi[t] + c
            else pi[x] = pi[p] - c;
        }
        return true;
    };

    int pivots = 0;
    const int max_pivots = n * m * 2;
    int stale = 0;
    while (pivots < max_pivots) {
        int es, et; double erc;
        if (!find_entering(es, et, erc)) {
            if (++stale > (n * m) / BLOCK + 2) break;
            continue;
        }
        stale = 0;
        if (!update_tree(es, et)) return 2;
        pivots++;
    }

    std::memset(flow_out, 0, (int64_t)n * m * sizeof(double));
    for (int x = 0; x < N; x++) {
        int p = parent[x];
        if (p < 0 || p == ROOT || x == ROOT) continue;
        int snode, tnode;
        if (x < n && p >= n) { snode = x; tnode = p - n; }
        else if (p < n && x >= n) { snode = p; tnode = x - n; }
        else continue;
        flow_out[(int64_t)snode * m + tnode] += flow[x];
    }
    return pivots;
}
EOF
