// Gauss-Seidel (asynchronous) auction with epsilon scaling. Each unassigned
// row bids once and the price is raised immediately, so conflicts resolve in
// far fewer scans than the Jacobi variant.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>

extern "C" int gs_auction(const double* M, int n, int64_t* col_of_row, int64_t* bids_out) {
    double maxc = 0.0;
    for (int64_t i = 0; i < (int64_t)n * n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 2.0;
    const double target = 1e-10;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), col_of(n, -1);

    int64_t bids = 0;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(col_of.begin(), col_of.end(), -1);
        int unassigned = n;
        int guard = 0;
        const int guard_max = n * n;
        int cursor = 0;
        while (unassigned > 0 && guard++ < guard_max) {
            // find next unassigned row
            int i = -1;
            for (int c = 0; c < n; c++) {
                int r = (cursor + c) % n;
                if (col_of[r] < 0) { i = r; cursor = r + 1; break; }
            }
            if (i < 0) break;
            const double* row = M + (int64_t)i * n;
            int j1 = 0;
            double best = -row[0] - price[0];
            double second = -1e300;
            for (int j = 1; j < n; j++) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; j1 = j; }
                else if (val > second) second = val;
            }
            double new_price = price[j1] + (best - second) + eps;
            int prev = owner[j1];
            if (prev >= 0) { col_of[prev] = -1; unassigned++; }
            owner[j1] = i;
            col_of[i] = j1;
            price[j1] = new_price;
            unassigned--;
            bids++;
        }
        if (unassigned > 0) return 1;
        std::fprintf(stderr, "eps %.3e bids_so_far %lld\n", eps, (long long)bids);
        if (eps <= target) break;
        eps *= 0.25;
        if (eps < target) eps = target;
    }
    for (int i = 0; i < n; i++) col_of_row[i] = col_of[i];
    if (bids_out) *bids_out = bids;
    return 0;
}
