// Jonker-Volgenant dense assignment with column reduction, reduction transfer
// and augmenting row reduction, followed by shortest augmenting paths.
// Cost matrix is row-major n x n.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>

extern "C" int jv_full(const double* M, int n, int64_t* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of(n, -1), col_of(n, -1);   // col -> row, row -> col

    // ---- column reduction ----
    for (int j = n - 1; j >= 0; j--) {
        double best = INF; int i_best = 0;
        for (int i = 0; i < n; i++) {
            double r = M[(int64_t)i * n + j] - u[i];
            if (r < best) { best = r; i_best = i; }
        }
        v[j] = best;
        if (col_of[i_best] < 0) { col_of[i_best] = j; row_of[j] = i_best; }
    }

    // ---- reduction transfer ----
    for (int i = 0; i < n; i++) if (col_of[i] < 0) {
        double best = INF, second = INF;
        for (int j = 0; j < n; j++) {
            double r = M[(int64_t)i * n + j] - v[j];
            if (r < best) { second = best; best = r; }
            else if (r < second) second = r;
        }
        u[i] = second - best > 0 ? best : best;  // placeholder, set below
        // transfer: lower v of columns tied for best
        double thresh = best;
        u[i] = 0; // recompute properly
        for (int j = 0; j < n; j++) {
            double r = M[(int64_t)i * n + j] - v[j];
            if (r <= thresh + 1e-12) v[j] -= (second - best);
        }
        u[i] = second;
    }

    // ---- augmenting row reduction ----
    for (int pass = 0; pass < 2; pass++) {
        for (int i = 0; i < n; i++) if (col_of[i] < 0) {
            double best = INF, second = INF; int j1 = -1;
            const double* row = M + (int64_t)i * n;
            for (int j = 0; j < n; j++) {
                double r = row[j] - v[j];
                if (r < best) { second = best; best = r; j1 = j; }
                else if (r < second) second = r;
            }
            double delta = second - best;
            v[j1] -= delta;
            u[i] = second;
            int i_prev = row_of[j1];
            if (i_prev >= 0) { col_of[i_prev] = -1; u[i_prev] -= delta; }
            row_of[j1] = i;
            col_of[i] = j1;
        }
    }

    int free_count = 0;
    for (int i = 0; i < n; i++) if (col_of[i] < 0) free_count++;
    std::fprintf(stderr, "free after init: %d\n", free_count);

    // ---- shortest augmenting paths for the remaining free rows ----
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> chain, newrow;

    for (int src = 0; src < n; src++) if (col_of[src] < 0) {
        std::memset(scanned.data(), 0, n);
        double us = u[src];
        const double* srow = M + (int64_t)src * n;
        for (int j = 0; j < n; j++) { dist[j] = srow[j] - us - v[j]; pred[j] = -1; }

        int sink = -1; double dsink = 0;
        while (true) {
            int jbest = -1; double dbest = INF;
            for (int j = 0; j < n; j++) if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            scanned[jbest] = 1;
            if (row_of[jbest] < 0) { sink = jbest; dsink = dbest; break; }
            int r = row_of[jbest];
            double ur = u[r];
            const double* rrow = M + (int64_t)r * n;
            for (int j = 0; j < n; j++) if (!scanned[j]) {
                double d = dbest + rrow[j] - ur - v[j];
                if (d < dist[j]) { dist[j] = d; pred[j] = jbest; }
            }
        }
        u[src] += dsink;
        for (int j = 0; j < n; j++) if (scanned[j]) {
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = row_of[j];
            if (r >= 0) u[r] -= delta;
        }
        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++) newrow[t] = (pred[chain[t]] < 0) ? src : row_of[pred[chain[t]]];
        for (int t = 0; t < L; t++) { row_of[chain[t]] = newrow[t]; col_of[newrow[t]] = chain[t]; }
    }

    for (int i = 0; i < n; i++) col_of_row[i] = col_of[i];
    return 0;
}
