// LAPJV-style dense assignment: column reduction, reduction transfer and
// augmenting row reduction, then shortest augmenting paths for the rest.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>

extern "C" int jv_full(const double* cost, int n, int64_t* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1);   // row -> col, col -> row
    std::vector<int> matches(n, 0);

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        double min = INF;
        int imin = 0;
        for (int i = 0; i < n; ++i) {
            double r = cost[(int64_t)i * n + j] - u[i];
            if (r < min) { min = r; imin = i; }
        }
        v[j] = min;
        if (++matches[imin] == 1) { rowsol[imin] = j; colsol[j] = imin; }
        else colsol[j] = -1;
    }
    for (int i = 0; i < n; i++) if (matches[i] == 0) rowsol[i] = -1;

    // reduction transfer
    for (int i = 0; i < n; i++) if (matches[i] == 0) {
        double min = INF;
        for (int j = 0; j < n; j++) {
            double r = cost[(int64_t)i * n + j] - v[j];
            if (r < min) min = r;
        }
        u[i] = min;
        for (int j = 0; j < n; j++) {
            if (cost[(int64_t)i * n + j] - v[j] - min < 1e-12 && colsol[j] < 0) {
                colsol[j] = i; rowsol[i] = j; matches[i] = 1; break;
            }
        }
    }

    // augmenting row reduction
    int free_count = 0;
    std::vector<int> free_rows(n);
    for (int i = 0; i < n; i++) if (rowsol[i] < 0) free_rows[free_count++] = i;

    for (int pass = 0; pass < n && free_count > 0; pass++) {
        int new_free = 0;
        for (int f = 0; f < free_count; f++) {
            int i = free_rows[f];
            double min1 = INF, min2 = INF; int j1 = -1;
            const double* row = cost + (int64_t)i * n;
            for (int j = 0; j < n; j++) {
                double r = row[j] - v[j];
                if (r < min1) { min2 = min1; min1 = r; j1 = j; }
                else if (r < min2) min2 = r;
            }
            v[j1] -= (min2 - min1);
            u[i] = min2;
            int i2 = colsol[j1];
            if (i2 >= 0) {
                if (u[i2] - (min2 - min1) < min2 - 1e-12) {
                    // previous row still competitive: it becomes free, we take the column
                    rowsol[i] = j1; colsol[j1] = i;
                    rowsol[i2] = -1;
                    free_rows[new_free++] = i2;
                } else {
                    free_rows[new_free++] = i;   // no progress, retry later
                }
            } else {
                rowsol[i] = j1; colsol[j1] = i;
            }
        }
        if (new_free == free_count) break;
        free_count = new_free;
    }

    int still_free = 0;
    for (int i = 0; i < n; i++) if (rowsol[i] < 0) still_free++;
    std::fprintf(stderr, "free after init: %d\n", still_free);

    // shortest augmenting path
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> chain, newrow;

    for (int src = 0; src < n; src++) if (rowsol[src] < 0) {
        std::memset(scanned.data(), 0, n);
        const double* srow = cost + (int64_t)src * n;
        for (int j = 0; j < n; j++) { dist[j] = srow[j] - u[src] - v[j]; pred[j] = -1; }
        int sink = -1; double dsink = 0;
        while (true) {
            int jbest = -1; double dbest = INF;
            for (int j = 0; j < n; j++) if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            scanned[jbest] = 1;
            if (colsol[jbest] < 0) { sink = jbest; dsink = dbest; break; }
            int r = colsol[jbest];
            const double* rrow = cost + (int64_t)r * n;
            for (int j = 0; j < n; j++) if (!scanned[j]) {
                double d = dbest + rrow[j] - u[r] - v[j];
                if (d < dist[j]) { dist[j] = d; pred[j] = jbest; }
            }
        }
        u[src] += dsink;
        for (int j = 0; j < n; j++) if (scanned[j]) {
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = colsol[j];
            if (r >= 0) u[r] -= delta;
        }
        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++) newrow[t] = (pred[chain[t]] < 0) ? src : colsol[pred[chain[t]]];
        for (int t = 0; t < L; t++) { colsol[chain[t]] = newrow[t]; rowsol[newrow[t]] = chain[t]; }
    }
    for (int i = 0; i < n; i++) col_of_row[i] = rowsol[i];
    return 0;
}
