// Gauss-Seidel auction down to a moderate epsilon, then exact shortest
// augmenting paths over the remaining suboptimal assignments. The auction
// supplies dual prices; rows whose matched edge is not dual-tight are freed
// and re-augmented exactly, which also repairs the dual.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>

extern "C" int hybrid(const double* M, int n, double target_eps, int64_t* col_of_row) {
    const double INF = 1e100;
    double maxc = 0.0;
    for (int64_t i = 0; i < (int64_t)n * n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 2.0;

    std::vector<double> price(n, 0.0), u(n, 0.0);
    std::vector<int> owner(n, -1), col_of(n, -1);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(col_of.begin(), col_of.end(), -1);
        int unassigned = n, guard = 0, cursor = 0;
        while (unassigned > 0 && guard++ < n * n) {
            int i = -1;
            for (int c = 0; c < n; c++) { int r = (cursor + c) % n; if (col_of[r] < 0) { i = r; cursor = r + 1; break; } }
            const double* row = M + (int64_t)i * n;
            int j1 = 0; double best = -row[0] - price[0], second = -1e300;
            for (int j = 1; j < n; j++) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; j1 = j; }
                else if (val > second) second = val;
            }
            double np_ = price[j1] + (best - second) + eps;
            int prev = owner[j1];
            if (prev >= 0) { col_of[prev] = -1; unassigned++; }
            owner[j1] = i; col_of[i] = j1; price[j1] = np_;
            unassigned--;
        }
        if (unassigned > 0) return 1;
        if (eps <= target_eps) break;
        eps *= 0.25;
        if (eps < target_eps) eps = target_eps;
    }

    // dual from auction: v = price, u[i] = M[i, col] - v[col] makes matched edges tight
    std::vector<double> v = price;
    for (int i = 0; i < n; i++) u[i] = M[(int64_t)i * n + col_of[i]] - v[col_of[i]];

    // free every row that has a negative reduced-cost edge and re-augment
    std::vector<int> row_of(n, -1);
    for (int i = 0; i < n; i++) row_of[col_of[i]] = i;

    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> chain, newrow;

    auto augment_from = [&](int src) {
        std::memset(scanned.data(), 0, n);
        const double* srow = M + (int64_t)src * n;
        for (int j = 0; j < n; j++) { dist[j] = srow[j] - u[src] - v[j]; pred[j] = -1; }
        int sink = -1; double dsink = 0;
        while (true) {
            int jbest = -1; double dbest = INF;
            for (int j = 0; j < n; j++) if (!scanned[j] && dist[j] < dbest) { dbest = dist[j]; jbest = j; }
            scanned[jbest] = 1;
            if (row_of[jbest] < 0 || row_of[jbest] == src) { sink = jbest; dsink = dbest; break; }
            int r = row_of[jbest];
            const double* rrow = M + (int64_t)r * n;
            for (int j = 0; j < n; j++) if (!scanned[j]) {
                double d = dbest + rrow[j] - u[r] - v[j];
                if (d < dist[j]) { dist[j] = d; pred[j] = jbest; }
            }
        }
        u[src] += dsink;
        for (int j = 0; j < n; j++) if (scanned[j]) {
            double delta = dist[j] - dsink;
            v[j] += delta;
            int r = row_of[j];
            if (r >= 0 && r != src) u[r] -= delta;
        }
        // free src's old column, then augment
        row_of[col_of[src]] = -1;
        chain.clear();
        for (int j = sink; j >= 0; j = pred[j]) chain.push_back(j);
        int L = (int)chain.size();
        newrow.resize(L);
        for (int t = 0; t < L; t++) newrow[t] = (pred[chain[t]] < 0) ? src : row_of[pred[chain[t]]];
        for (int t = 0; t < L; t++) { row_of[chain[t]] = newrow[t]; col_of[newrow[t]] = chain[t]; }
    };

    int repairs = 0;
    for (int iter = 0; iter < n; iter++) {
        bool changed = false;
        for (int i = 0; i < n; i++) {
            const double* row = M + (int64_t)i * n;
            double ui = u[i];
            double worst = -1e-9;
            for (int j = 0; j < n; j++) {
                double r = row[j] - ui - v[j];
                if (r < worst) worst = r;
            }
            if (worst < -1e-9) { augment_from(i); repairs++; changed = true; }
        }
        if (!changed) break;
    }
    std::fprintf(stderr, "repairs %d\n", repairs);
    for (int i = 0; i < n; i++) col_of_row[i] = col_of[i];
    return 0;
}
