    std::vector<int> owner(n, -1), col_of(n, -1);

    while (true) {
        int unassigned = 0;
        for (int i = 0; i < n; i++) if (col_of[i] < 0) unassigned++;
        int guard = 0, cursor = 0;
        while (unassigned > 0 && guard++ < n * n * 4) {
            int i = -1;
            for (int c = 0; c < n; c++) {
                int r = (cursor + c) % n;
                if (col_of[r] < 0) { i = r; cursor = r + 1; break; }
            }
            const double* row = M + (int64_t)i * n;
            int j1 = 0;
            double best = -row[0] - price[0];
            double second = -1e300;
            for (int j = 1; j < n; j++) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; j1 = j; }
                else if (val > second) second = val;
            }
            double np_ = price[j1] + (best - second) + eps;
            int prev = owner[j1];
            if (prev >= 0 && prev != i) { col_of[prev] = -1; unassigned++; }
            owner[j1] = i;
