// Gauss-Seidel auction, AVX2 bidding scan. Prices persist across epsilon
// phases; assignments are recomputed at each phase.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <immintrin.h>

extern "C" int gs_auction(const double* M, int n, double target, int64_t* col_of_row) {
    double maxc = 0.0;
    for (int64_t i = 0; i < (int64_t)n * n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 2.0;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), col_of(n, -1);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(col_of.begin(), col_of.end(), -1);
        int unassigned = n, guard = 0, cursor = 0;
        while (unassigned > 0 && guard++ < n * n * 4) {
            int i = -1;
            for (int c = 0; c < n; c++) {
                int r = (cursor + c) % n;
                if (col_of[r] < 0) { i = r; cursor = r + 1; break; }
            }
            const double* row = M + (int64_t)i * n;
            // best and second best of -row[j] - price[j]
            __m256d best = _mm256_set1_pd(-1e300);
            __m256d second = best;
            __m256d bestj = _mm256_setzero_pd();
            int j = 0;
            for (; j + 4 <= n; j += 4) {
                __m256d val = _mm256_sub_pd(_mm256_sub_pd(_mm256_setzero_pd(), _mm256_loadu_pd(row + j)),
                                            _mm256_loadu_pd(price.data() + j));
                __m256d idx = _mm256_set_pd(j + 3, j + 2, j + 1, j);
                // val > best?
                __m256d gt = _mm256_cmp_pd(val, best, _CMP_GT_OQ);
                __m256d newsecond = _mm256_blendv_pd(second, _mm256_max_pd(second, best), gt);
                // also second = max(second, val) where val <= best
                __m256d le = _mm256_cmp_pd(val, best, _CMP_LE_OQ);
