// Sparse Gauss-Seidel auction: each row bids among its k nearest columns.
// Prices persist across epsilon phases; assignments restart each phase.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>

static void knn(const double* row, int n, int k, int* cols, double* costs) {
    auto sift = [&](int len, int i) {
        while (true) {
            int l = 2 * i + 1, r = l + 1, big = i;
            if (l < len && costs[l] > costs[big]) big = l;
            if (r < len && costs[r] > costs[big]) big = r;
            if (big == i) break;
            std::swap(costs[i], costs[big]);
::std::swap(cols[i], cols[big]);
            i = big;
        }
    };
    for (int j = 0; j < k; j++) { cols[j] = j; costs[j] = row[j]; }
    for (int i = k / 2 - 1; i >= 0; i--) sift(k, i);
    for (int j = k; j < n; j++) if (row[j] < costs[0]) { costs[0] = row[j]; cols[0] = j; sift(k, 0); }
}

extern "C" int gs_k(const double* M, int n, int k, double target, int64_t* col_of_row) {
    if (k > n) k = n;
    std::vector<int> cc((int64_t)n * k);
    std::vector<double> cv((int64_t)n * k);
    for (int i = 0; i < n; i++) knn(M + (int64_t)i * n, n, k, cc.data() + (int64_t)i * k, cv.data() + (int64_t)i * k);

    double maxc = 0.0;
    for (double x : cv) if (x > maxc) maxc = x;
    double eps = maxc / 2.0;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), col_of(n, -1);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(col_of.begin(), col_of.end(), -1);
        int unassigned = n, guard = 0, cursor = 0;
        while (unassigned > 0 && guard++ < n * n) {
            int i = -1;
            for (int c = 0; c < n; c++) {
                int r = (cursor + c) % n;
                if (col_of[r] < 0) { i = r; cursor = r + 1; break; }
            }
            const int* cols = cc.data() + (int64_t)i * k;
            const double* costs = cv.data() + (int64_t)i * k;
            int j1 = cols[0];
            double best = -costs[0] - price[j1];
            double second = -1e300;
            for (int t = 1; t < k; t++) {
                int j = cols[t];
                double val = -costs[t] - price[j];
                if (val > best) { second = best; best = val; j1 = j; }
                else if (val > second) second = val;
            }
            double np_ = price[j1] + (best - second) + eps;
            int prev = owner[j1];
            if (prev >= 0 && prev != i) { col_of[prev] = -1; unassigned++; }
            owner[j1] = i; col_of[i] = j1; price[j1] = np_;
            unassigned--;
        }
        if (unassigned > 0) return 1;
        if (eps <= target) break;
        eps *= 0.25;
        if (eps < target) eps = target;
    }
    for (int i = 0; i < n; i++) col_of_row[i] = col_of[i];
    return 0;
}
