// Gauss-Seidel auction. Unassigned rows live in an explicit stack, so a bid
// never scans for the next free row. Prices persist across epsilon phases.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>

extern "C" int gs_auction(const double* M, int n, double target, int64_t* col_of_row) {
    double maxc = 0.0;
    for (int64_t i = 0; i < (int64_t)n * n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 2.0;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> stack(n);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        int top = n;
        for (int i = 0; i < n; i++) stack[i] = i;
        int guard = 0;
        const int guard_max = n * n * 4;
        while (top > 0 && guard++ < guard_max) {
            int i = stack[--top];
            const double* row = M + (int64_t)i * n;
            int j1 = 0;
            double best = -row[0] - price[0];
            double second = -1e300;
            for (int j = 1; j < n; j++) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; j1 = j; }
                else if (val > second) second = val;
            }
            price[j1] += (best - second) + eps;
            int prev = owner[j1];
            if (prev >= 0) stack[top++] = prev;
            owner[j1] = i;
        }
        if (top > 0) return 1;
        if (eps <= target) break;
        eps *= 0.25;
        if (eps < target) eps = target;
    }
    for (int j = 0; j < n; j++) col_of_row[owner[j]] = j;
    return 0;
}
